/**
 * Release gate: every check a deployment must pass, in dependency order, stopping at the first failure.
 *
 *   npm run release:check                    # production configuration preflight (needs the build environment)
 *   npm run release:check -- --target local  # local rehearsal without production settings
 *
 * Type checking runs after the build because route types are generated by `next build`; the CMS exclusion and
 * browser-bundle scans inspect that build output. Stop any `next dev` server for this checkout first so the build
 * and scans see only production output. No step sends email, calls a hosted service, or writes canonical content
 * (the localization checks write reports only under the gitignored .glossary-drafts/).
 */
import { spawn } from "node:child_process";
import { parseArgs } from "node:util";

type Step = Readonly<{ label: string; command: string }>;

function steps(target: string): Step[] {
  return [
    { label: "Configuration preflight (web)", command: `npm run -s config:check -- --target ${target}` },
    { label: "Lint", command: "npm run -s lint" },
    { label: "Unit and integration tests", command: "npx vitest run" },
    { label: "Architecture boundaries", command: "npm run -s architecture:check" },
    { label: "Editorial state audit", command: "npm run -s editorial:audit" },
    { label: "Guidance coverage audit", command: "npm run -s editorial:coverage:audit" },
    { label: "Localization audit", command: "npm run -s localization:audit" },
    { label: "Article translation check", command: "npm run -s localization:articles:check" },
    { label: "Glossary consistency check", command: "npm run -s localization:glossary:check" },
    { label: "Production build", command: "npx next build" },
    { label: "Type check (after build)", command: "npx tsc --noEmit -p ." },
    { label: "CMS exclusion scan", command: "npm run -s cms:check-build" },
    { label: "Browser bundle boundary", command: "npm run -s bundle:check" },
  ];
}

function run(command: string): Promise<number> {
  return new Promise((resolve) => {
    const child = spawn(command, { stdio: "inherit", shell: true });
    child.on("close", (code) => resolve(code ?? 1));
    child.on("error", () => resolve(1));
  });
}

async function main(): Promise<void> {
  const { values } = parseArgs({ options: { target: { type: "string", default: "production" } } });
  if (values.target !== "production" && values.target !== "local") throw new Error('--target must be "production" or "local".');
  const plan = steps(values.target);
  const results: { label: string; seconds: number; passed: boolean }[] = [];
  for (const [index, step] of plan.entries()) {
    console.log(`\n▶ [${index + 1}/${plan.length}] ${step.label}`);
    const started = performance.now();
    const passed = (await run(step.command)) === 0;
    results.push({ label: step.label, seconds: (performance.now() - started) / 1000, passed });
    if (!passed) break;
  }
  console.log("\nRelease check summary:");
  for (const { label, seconds, passed } of results) console.log(`  ${passed ? "pass" : "FAIL"}  ${label} (${seconds.toFixed(1)}s)`);
  const skipped = plan.slice(results.length);
  for (const { label } of skipped) console.log(`  skip  ${label}`);
  if (results.some(({ passed }) => !passed)) {
    process.exitCode = 1;
    return;
  }
  console.log(`All ${plan.length} release checks passed (target: ${values.target}).`);
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
